# text it points to it 
# Looking for a backend developer with experience in Python and FastAPI.

def similar_project(session: Session, job:JobCreate ) -> List[Project]:
    #job_embedding = generate_embedding(job.job_description)
    job_embedding = fixed_embedding
    #print("Job Embedding Generated: ", job_embedding)
    project_list=session.query(Project).order_by(
        Project.embedding.cosine_distance(job_embedding)
    ).limit(1).all()
    return project_list

# For Testing the function independently

# YOU NEED TO RUN THIS AS MODULE 
# uv run python -m  db.operations.similarity other wise it will treate anything in operations directory as package and will give import error
# This will make sure that Porject is directory and folders isnide it is treated as package 

if __name__ == "__main__":
    from db.session import SessionLocal
    db = SessionLocal()
    job_data = JobCreate(
        job_description="Looking for a backend developer with experience in Python and FastAPI.",
        created_by="sid"
    )
    similar_projects = similar_project(db, job_data)
    for project in similar_projects:
        print(f"Project Title: {project.title}, Description: {project.description}")
    db.close()

